async function fetchModels(s:BrainSlot){if(backend?.voice_active||backend?.busy){if(!await command('conversation-interrupt'))return}if(!keyReady(s)){setError('Paste your '+s.provider+' API key into this account field, then Save & test. Never paste keys into chat.');return}if(!s.enabled){setError('Enable '+s.id+' before testing.');return}if(!s.consent||!s.free){setError('Confirm context sharing and free/no-billing access for '+s.id+' before testing.');return}try{if(secrets[s.id]){const secret=secrets[s.id];await call('key-save',{slot:s.id,kind:s.provider,secret});setSecrets(old=>({...old,[s.id]:''}))}const b=await call('brain-save',{slots:slots.map(x=>({id:x.id,provider:x.provider,model:x.model,enabled:x.enabled,consent:x.consent,free:x.free,label:x.label||''})),assignments:Object.fromEntries(Object.entries(routes).filter(([,id])=>slots.some(x=>x.id===id&&x.enabled)))});setBackend(b);pendingAutoModel.current=null;await command('brain-models',{slot:s.id})}catch(x){setError(String(x))}}
async function saveKey(s:BrainSlot){const secret=secrets[s.id]||'';if(await command('key-save',{slot:s.id,kind:s.provider,secret})){setSavedKeys(old=>({...old,[s.provider+'/'+s.id]:true}));setSecrets(old=>({...old,[s.id]:''}))}}

